/**
 * Facts extracted from private gameplay captures (colosseum-waves-1-12-damage-trials-solarflare3-volatility3-bees1-totemic-doom1-death-packet-data.txt
 * as `waves`, colosseum-no-sol-packet-data.txt as `noSol`, colosseum-waves-bees-death(no-sol)-packet-data-1.txt
 * as `bees`). Manticores (npc 12818) in three Colosseum runs; the per-tick groups use `waves` and `noSol`.
 * Tiles are relative to the Colosseum arena origin (world 1792, 3072).
 *
 * `MANTICORE_CAPTURE_GROUPS` has one entry per wave: each Manticore present together (NPC index, add tick and
 * tile, and the ticks of its charge sequence 10868, throw sequence 10869, each orb projectile with its style and
 * source tile, its death sequence 10866 and its removal, and `heldOrbs`: the orb spotanims held in its slots 1-3
 * as `[id, height]`, bottom slot first, from each tick on which they change: a slot holds from its id until its
 * `id=-1` clear, and none is re-sent on the death-sequence tick), plus `track`, the local player's start-of-tick tile
 * and each Manticore's tile after that tick's movement (`null` before its add or after its death sequence),
 * listed only on the ticks where one of them changes.
 *
 * `MANTICORE_PRAYER_CAPTURE` has orbs around a protection-prayer switch: launch tick, style, the protection
 * prayer active after the launch tick's input and after the next tick's, and the player's splats on landing
 * as `[splat id, value]` (12 = blocked zero, 16 = damage; other sources share the tick in C:2018, B:3179).
 */
import type { Coordinate } from '../../../../types/simulation';

export type CapturedOrbStyle = 'ranged' | 'magic' | 'melee';

export interface ManticoreCaptureMember {
  readonly index: number;
  readonly addTick: number;
  readonly addTile: Coordinate;
  readonly charges: readonly number[];
  readonly throws: readonly number[];
  readonly orbs: readonly (readonly [tick: number, style: CapturedOrbStyle, source: Coordinate])[];
  readonly deathSequenceTick: number | null;
  readonly removalTick: number | null;
  readonly heldOrbs: readonly (readonly [tick: number, orbs: readonly (readonly [id: number, height: number])[]])[];
}

export interface ManticoreCaptureGroup {
  readonly capture: 'waves' | 'noSol';
  readonly members: readonly ManticoreCaptureMember[];
  readonly endTick: number;
  /** `[tick, playerStart, ...memberTiles]`, in `members` order. */
  readonly track: readonly (readonly [number, Coordinate, ...(Coordinate | null)[]])[];
}

